bootstrap:
(
set -eu
set +x
# Read the entire pinned launcher before executing it.
ovos=$(curl -qfsS --proto '=https' --connect-timeout 15 -m 120 'https://raw.githubusercontent.com/goldyfruit/ovos-start-launcher/aa528a5e0ce50ccc43c26e1964067a0e0464f272/v2.sh') || { printf '%s\n' 'Could not download the installer. Please try again.' >&2; exit 1; }
[ -n "$ovos" ] || { printf '%s\n' 'The installer download was empty. Please try again.' >&2; exit 1; }
# Keep interactive installer prompts on the terminal, not the download pipe.
[ -r /dev/tty ] && ( : < /dev/tty ) 2>/dev/null || { printf '%s\n' 'Open Terminal on your OVOS device and paste the command there.' >&2; exit 1; }
exec sh -c "$ovos" -- '4400-00G0-DD4X-406N' --track 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb' < /dev/tty
)
